def _enumerate_paths(n, out_edges, e_v):
    """All source-to-destination edge-ID paths in the full graph, with bitmasks.

    Only nodes that can still reach the destination are explored, and the
    enumeration is capped at the documented bound of MAX_PATHS paths.
    """
    reach = [False] * n
    reach[n - 1] = True
    for v in range(n - 2, -1, -1):
        for oe in out_edges[v]:
            if reach[e_v[oe]]:
                reach[v] = True
                break
    paths = []
    masks = []
    if not reach[0]:
        return paths, masks
    stack_path = []

    def dfs(node, mask):
        for oe in out_edges[node]:
            v = e_v[oe]
            if not reach[v]:
                continue
            stack_path.append(oe)
            child_mask = mask | (1 << oe)
            if v == n - 1:
                paths.append(tuple(stack_path))
                masks.append(child_mask)
                if len(paths) > MAX_PATHS:
                    raise _Invalid("too many paths")
            else:
                dfs(v, child_mask)
            stack_path.pop()

    dfs(0, 0)
    return paths, masks


