import json, random, subprocess, sys

def gen1(rng):
    n = rng.randint(2, 9)
    labels_pool = ["a","b","c","d","e","a","b"]
    edges, seen = [], set()
    for u in range(n):
        for v in range(u+1, n):
            if rng.random() < 0.45 and (u,v) not in seen:
                seen.add((u,v))
                edges.append({"u":u,"v":v,"ping_us":rng.choice([1,1,1,2,2,3,5,8]),
                              "ack_us":rng.choice([1,1,1,2,2,3,5,8]),
                              "label":rng.choice(labels_pool)})
    if rng.random() < 0.7:
        u = 0
        for v in range(1, n):
            if (u,v) not in seen:
                seen.add((u,v)); edges.append({"u":u,"v":v,"ping_us":rng.choice([1,1,2,3]),
                              "ack_us":rng.choice([1,1,2,3]),"label":rng.choice(labels_pool)})
            u = v
    nr = rng.randint(0, 6)
    rounds = []
    for _ in range(nr):
        rounds.append({"launch_us": rng.choice([0,0,1,2,3,5,8,13,20]),
                       "timeout_us": rng.choice([1,2,3,4,5,6,8,10,14,20,40]),
                       "host_delay_us": rng.choice([1,1,2,3]),
                       "drop_host_ack": rng.random() < 0.15,
                       "drop_ping": sorted(rng.sample(range(len(edges)), rng.randint(0, min(2, len(edges)))) if edges else []),
                       "drop_ack": sorted(rng.sample(range(len(edges)), rng.randint(0, min(2, len(edges)))) if edges else [])})
    return {"version":1,"n":n,"capacity":[rng.choice([0,1,1,2,2,3,48]) for _ in range(n)],
            "edges":edges,"rounds":rounds}

def gen2(rng, style):
    if style == 0:
        n = rng.randint(2, 6)
        edges, seen = [], set()
        for u in range(n):
            for v in range(u+1, n):
                if rng.random() < 0.6 and (u,v) not in seen:
                    seen.add((u,v))
                    edges.append({"u":u,"v":v,"ping_us":rng.choice([1,1,2]),
                                  "ack_us":rng.choice([1,1,2]),"label":rng.choice(["a","a","a","b"])})
        if rng.random() < 0.6:
            u=0
            for v in range(1,n):
                if (u,v) not in seen:
                    seen.add((u,v)); edges.append({"u":u,"v":v,"ping_us":1,"ack_us":1,"label":rng.choice(["a","a","b"])})
                u=v
        rounds=[{"launch_us":rng.choice([0,0,0,1,2]),"timeout_us":rng.choice([1,1,2,2,3,3,4,5,6]),
                 "host_delay_us":rng.choice([1,1,2]),"drop_host_ack":rng.random()<0.1,
                 "drop_ping":[],"drop_ack":[]} for _ in range(rng.randint(0,8))]
        return {"version":1,"n":n,"capacity":[rng.choice([0,1,1,2,2]) for _ in range(n)],"edges":edges,"rounds":rounds}
    elif style == 1:
        n = rng.randint(3, 8)
        edges = []
        for u in range(n):
            for v in range(u+1,n):
                if rng.random() < 0.5:
                    edges.append({"u":u,"v":v,"ping_us":rng.randint(1,7),"ack_us":rng.randint(1,7),
                                   "label":rng.choice(["a","b","c","0","a"])})
        if not any(e["u"]==0 and e["v"]==n-1 for e in edges):
            edges.append({"u":0,"v":n-1,"ping_us":1,"ack_us":1,"label":"a"})
        ne = len(edges)
        rounds=[{"launch_us":rng.choice([0,1,3,7,15]),"timeout_us":rng.choice([2,4,8,12,16,30]),
                 "host_delay_us":rng.randint(1,4),"drop_host_ack":rng.random()<0.25,
                 "drop_ping":rng.sample(range(ne), rng.randint(0,min(4,ne))),
                 "drop_ack":rng.sample(range(ne), rng.randint(0,min(4,ne)))} for _ in range(rng.randint(1,5))]
        return {"version":1,"n":n,"capacity":[rng.choice([1,2,3,48]) for _ in range(n)],"edges":edges,"rounds":rounds}
    else:
        n = rng.randint(2, 16)
        edges = []
        for i in range(n-1):
            edges.append({"u":i,"v":i+1,"ping_us":rng.choice([1,1,2,3]),"ack_us":rng.choice([1,1,2,3]),
                          "label":rng.choice(["a","b","a","b"])})
            if i+2 < n and rng.random() < 0.8:
                edges.append({"u":i,"v":i+2,"ping_us":rng.choice([1,1,3]),"ack_us":rng.choice([1,1,3]),
                              "label":rng.choice(["a","b","a","b"])})
        rounds=[{"launch_us":rng.choice([0,0,1,2]),"timeout_us":rng.choice([1,1,2,3,5]),
                 "host_delay_us":rng.choice([1,1,2]),"drop_host_ack":rng.random()<0.2,
                 "drop_ping":rng.sample(range(len(edges)), rng.randint(0,min(3,len(edges)))),
                 "drop_ack":rng.sample(range(len(edges)), rng.randint(0,min(3,len(edges))))} for _ in range(rng.randint(1,10))]
        return {"version":1,"n":n,"capacity":[rng.choice([0,1,2,48]) for _ in range(n)],"edges":edges,"rounds":rounds}

def gen4(rng):
    n = rng.randint(2, 7)
    edges, seen = [], set()
    lp = ["a"] if rng.random() < 0.5 else ["a","b","a","b"]
    for u in range(n):
        for v in range(u+1,n):
            if rng.random() < 0.7 and (u,v) not in seen:
                seen.add((u,v))
                edges.append({"u":u,"v":v,"ping_us":1,"ack_us":1,"label":rng.choice(lp)})
    if rng.random() < 0.3:
        u=0
        for v in range(1,n):
            if (u,v) not in seen:
                seen.add((u,v)); edges.append({"u":u,"v":v,"ping_us":1,"ack_us":1,"label":rng.choice(lp)})
            u=v
    rounds=[{"launch_us":rng.choice([0,0,1,1,2]),"timeout_us":rng.choice([1,1,2,2,3,4,5]),
             "host_delay_us":rng.choice([1,1,2]),"drop_host_ack":rng.random()<0.1,
             "drop_ping":rng.sample(range(len(edges)), rng.randint(0,min(2,len(edges)))) if edges else [],
             "drop_ack":rng.sample(range(len(edges)), rng.randint(0,min(2,len(edges)))) if edges else []}
            for _ in range(rng.randint(1,8))]
    cap = [rng.choice([0,1,1,2]) for _ in range(n)]
    return {"version":1,"n":n,"capacity":cap,"edges":edges,"rounds":rounds}

bad = 0
count = 0
for i in range(1200):
    for gen, arg in ((gen1, None), (gen4, None), (gen2, i % 3)):
        rng = random.Random(i * 131 + arg if isinstance(arg,int) else i)
        doc = gen(rng) if arg is None else gen(rng, arg)
        count += 1
        p = subprocess.run([sys.executable, "-I", '/workspace/tmp/main_instr.py'],
                           input=json.dumps(doc).encode(), capture_output=True)
        if p.returncode != 0 or b"DUP EVENT" in p.stderr:
            print("ANOMALY rc=%s" % p.returncode, p.stderr.decode()[:200])
            print(json.dumps(doc)[:300])
            bad += 1
print("checked:", count, "anomalies:", bad)
